test('issueInvoice uses existing numbers to calculate next', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const existing = ['INV-2026-0001', 'INV-2026-0002'];
  const issued = issueInvoice(result.value, existing);
  assert.equal(issued.value.number, 'INV-2026-0003');
});

test('issueInvoice handles different years', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2027-01-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const existing = ['INV-2026-9999'];
  const issued = issueInvoice(result.value, existing);
  assert.equal(issued.value.number, 'INV-2027-0001');
});

test('issueInvoice rejects non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 }],
  };
  const issued = issueInvoice(invoice, []);
  assert.deepEqual(issued, { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });
  const original = JSON.stringify(result.value);
  issueInvoice(result.value, []);
  assert.equal(JSON.stringify(result.value), original);
});
